from module_adapters._graph_extended_support import Diagram,validate
SOURCE='dgl-graph-modules/examples/pytorch/vgae/model.py';KEY='vgae_posterior'
LINKS=[('features','shared','features','tensor'),('g','shared','graph','topology'),('shared','mean','h','tensor'),('shared','logstd','h','tensor'),('g','mean','graph','topology'),('g','logstd','graph','topology'),('logstd','exp','in','tensor'),('features','noise','N','shape_dependency'),('device','noise','device','control'),('device','exp','device','control'),('noise','multiply','epsilon','tensor'),('exp','multiply','std','tensor'),('mean','add','mean','tensor'),('multiply','add','scaled_noise','tensor'),('add','output','in','tensor')]
REQUIRED={'shared':dict(instance_identity='layers.0',parameter_scope='layers.0',activation='relu',opaque_library=True),'mean':dict(instance_identity='layers.1',parameter_scope='layers.1',activation='identity',opaque_library=True),'logstd':dict(instance_identity='layers.2',parameter_scope='layers.2',activation='identity',opaque_library=True),'noise':dict(expression='torch.randn(features.size(0), self.hidden2_dim).to(device)',value_dependent_on_features=False,always_sample=True),'exp':dict(expression='torch.exp(self.log_std).to(device)',log_quantity='log_std',variance_halved=False),'add':dict(expression='self.mean + gaussian_noise * torch.exp(self.log_std).to(device)')}
CONTRACTS=[('VGAEModel.__init__','nn.ModuleList(layers)'),('VGAEModel.encoder','self.layers[0](g, features)'),('VGAEModel.encoder','self.layers[1](g, h)'),('VGAEModel.encoder','self.layers[2](g, h)'),('VGAEModel.encoder','torch.randn(features.size(0), self.hidden2_dim).to(device)'),('VGAEModel.encoder','self.mean + gaussian_noise * torch.exp(self.log_std).to(device)')]
def build():
 d=Diagram(KEY,'VGAE graph posterior sampling',SOURCE,'VGAEModel.encoder','Only VGAEModel.encoder posterior, not decoder/reconstruction/loss. GraphConv implementations kept explicitly opaque; exact constructor flags preserved.',dict(in_dim=8,hidden1_dim=16,hidden2_dim=8,shared_base='layers.0',independent_heads=['layers.1','layers.2'],distribution_quantity='log_std',always_samples=True,eval_mean_shortcut=False,device_origin='from train import device',graphconv_boundary='opaque DGL library, not expanded',allow_zero_in_degree=True))
 init=d.ref('VGAEModel.__init__');d.ref('__module__')
 d.input('features','Node features','[N,8]');d.input('g','Supplied DGL graph','N nodes / E edges',kind='control');d.input('device','Imported global device','from train import device',kind='control',source=d.ref('__module__'),runtime_boundary=True)
 d.node('shared','layers0 GraphConv8 -> 16 / ReLU','conv','[N,16]',0,source=[init,d.entry],**REQUIRED['shared'],allow_zero_in_degree=True)
 d.node('mean','layers1 GraphConv16 -> 8 / MEAN','conv','[N,8]',1,source=[init,d.entry],**REQUIRED['mean'],allow_zero_in_degree=True)
 d.node('logstd','layers2 GraphConv16 -> 8 / LOG STD','conv','[N,8]',1,source=[init,d.entry],**REQUIRED['logstd'],allow_zero_in_degree=True)
 d.node('noise','Fresh Gaussian noise / to(device)','control','[N,8]',2,**REQUIRED['noise']);d.node('exp','exp(log_std) / to(device)','activation','[N,8]',2,**REQUIRED['exp']);d.node('multiply','epsilon * standard deviation','multiply','[N,8]',3);d.node('add','mean + epsilon * std','add','[N,8]',4,**REQUIRED['add'])
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if s in ('g','device') or p=='N' or s=='mean' else 'out',ds='left' if s in ('g','device') or p=='N' or s=='mean' else 'in')
 return d.build(d.entry,'[N,8]','VGAEPosterior.md',['Three GraphConv instances are owned in ModuleList: one shared base and two independent posterior heads. Heads consume the SAME h and supplied graph, while weights are not shared.','Source predicts log_std, so standard deviation is exp(log_std), with no log variance/2 operation.','Fresh randn(N,hidden2_dim) occurs unconditionally even in eval mode; features supplies only the N shape to random generation. Global device comes from train import and is a runtime boundary.','GraphConv implementation is deliberately not expanded in this example; glyphs state opaque DGL library, exact widths, activation and allow_zero_in_degree flags. No GCN formula or self-loop preprocessing is invented.'],['Do not replace log_std with log_var, introduce an eval shortcut returning mean, or feed feature values into Gaussian noise.','Do not include adjacency decoder in the posterior module; it has a separate inner_product_decoder adapter.'])
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(always_samples=True,eval_mean_shortcut=False,distribution_quantity='log_std',independent_heads=['layers.1','layers.2']))
